      const draft = createBgpUcRedistributeDraft(bgpUcRedistributeDraft.value?.afKey, bgpUcRedistributeDraft.value);
      draft.protocol = String(draft.protocol || '').trim();
      draft.metric = String(draft.metric || '').trim();
