      bgpMcNetworkRows.value[afKey] = (bgpMcNetworkRows.value[afKey] || []).filter(item => !selected.has(String(item.__id)));
      pendingBgpMcNetworkDeleteIds.value = [];
      bgpMcNetworkDeleteVisible.value = false;
      persistBgpMcRowsToCli(afKey);
